package com.tripmateai.controller; import com.tripmateai.dto.request.budget.*; import com.tripmateai.dto.response.*; import com.tripmateai.dto.response.budget.*; import com.tripmateai.service.BudgetService; import com.tripmateai.util.ResponseUtils; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/trips/{tripId}/budget") @RequiredArgsConstructor public class BudgetController {private final BudgetService service; @PostMapping public ResponseEntity<ApiResponse<BudgetResponse>> create(@PathVariable Long tripId,@Valid @RequestBody BudgetRequest r){return ResponseUtils.created(service.create(tripId,r),"Budget created");} @GetMapping public ResponseEntity<ApiResponse<BudgetResponse>> get(@PathVariable Long tripId){return ResponseUtils.success(service.get(tripId),"Budget retrieved");} @PutMapping public ResponseEntity<ApiResponse<BudgetResponse>> update(@PathVariable Long tripId,@Valid @RequestBody UpdateBudgetRequest r){return ResponseUtils.success(service.update(tripId,r),"Budget updated");} @DeleteMapping public ResponseEntity<ApiResponse<Void>> delete(@PathVariable Long tripId){service.delete(tripId);return ResponseUtils.success(null,"Budget deleted");} @GetMapping("/summary") public ResponseEntity<ApiResponse<BudgetSummaryResponse>> summary(@PathVariable Long tripId){return ResponseUtils.success(service.summary(tripId),"Budget summary retrieved");}}
